import os
from typing import Any, Dict, List, Optional

import assemblyai as aai


def _normalize_words(words: Any) -> List[Dict[str, Any]]:
    normalized = []
    if not words:
        return normalized
    for w in words:
        if isinstance(w, dict):
            normalized.append(
                {
                    "text": w.get("text"),
                    "start": w.get("start"),
                    "end": w.get("end"),
                    "confidence": w.get("confidence"),
                }
            )
        else:
            normalized.append(
                {
                    "text": getattr(w, "text", None),
                    "start": getattr(w, "start", None),
                    "end": getattr(w, "end", None),
                    "confidence": getattr(w, "confidence", None),
                }
            )
    return normalized


def _normalize_segments(utterances: Any) -> List[Dict[str, Any]]:
    normalized = []
    if not utterances:
        return normalized
    for u in utterances:
        if isinstance(u, dict):
            normalized.append(
                {
                    "speaker": u.get("speaker"),
                    "text": u.get("text"),
                    "start": u.get("start"),
                    "end": u.get("end"),
                    "confidence": u.get("confidence"),
                    "words": _normalize_words(u.get("words")),
                }
            )
        else:
            normalized.append(
                {
                    "speaker": getattr(u, "speaker", None),
                    "text": getattr(u, "text", None),
                    "start": getattr(u, "start", None),
                    "end": getattr(u, "end", None),
                    "confidence": getattr(u, "confidence", None),
                    "words": _normalize_words(getattr(u, "words", None)),
                }
            )
    return normalized


def batch_speech_to_text_with_timestamps(
    audio_urls: List[str],
    *,
    word_timestamps: bool = True,
    segment_timestamps: bool = False,
    language_code: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Transcribe a batch of audio files with AssemblyAI and return word or segment timestamps.

    Args:
        audio_urls: List of public audio URLs to transcribe.
        word_timestamps: If True, include word-level timestamps.
        segment_timestamps: If True, include segment/utterance-level timestamps.
        language_code: Optional language code for transcription.

    Returns:
        A list of transcription results, one per audio URL, each containing
        transcript metadata and requested timestamps.
    """
    api_key = os.getenv("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise ValueError("ASSEMBLYAI_API_KEY environment variable is required.")

    aai.settings.api_key = api_key

    results: List[Dict[str, Any]] = []

    for audio_url in audio_urls:
        config_kwargs: Dict[str, Any] = {}
        if word_timestamps:
            config_kwargs["word_boost"] = []
            config_kwargs["punctuate"] = True
            config_kwargs["format_text"] = True
            config_kwargs["speaker_labels"] = segment_timestamps
            config_kwargs["disfluencies"] = False
            config_kwargs["auto_highlights"] = False
            config_kwargs["language_code"] = language_code

        transcript = aai.Transcriber().transcribe(
            audio_url,
            config=aai.TranscriptionConfig(**{k: v for k, v in config_kwargs.items() if v is not None}),
        )

        if getattr(transcript, "status", None) == aai.TranscriptStatus.error:
            raise RuntimeError(f"Transcription failed for {audio_url}: {getattr(transcript, 'error', 'unknown error')}")

        item: Dict[str, Any] = {
            "audio_url": audio_url,
            "id": getattr(transcript, "id", None),
            "status": getattr(transcript, "status", None),
            "text": getattr(transcript, "text", None),
        }

        if word_timestamps:
            item["words"] = _normalize_words(getattr(transcript, "words", None))

        if segment_timestamps:
            segments = getattr(transcript, "utterances", None)
            if segments is None:
                segments = getattr(transcript, "sentences", None)
            item["segments"] = _normalize_segments(segments)

        results.append(item)

    return results
